export function lookupRosenToken(
  chain: string | null | undefined,
  tokenId: string | null | undefined
): RosenTokenInfo | null {
  const id = (tokenId ?? "").trim();
  if (!id) return null;
  const ch = (chain ?? "").trim();
  const keys: string[] = [];
  if (ch) {
    keys.push(`${ch}:${id}`);
    if (id !== id.toLowerCase()) keys.push(`${ch}:${id.toLowerCase()}`);
  }
  keys.push(id);
  if (id !== id.toLowerCase()) keys.push(id.toLowerCase());
  for (const k of keys) {
    const hit = ROSEN_TOKENS[k];
    if (hit) return hit;
  }
  return null;
}
